svg.desc:
// clk rising edge; rst_n synchronous active-low clears every valid and ovf flag; datapath registers have no reset.
// The pipeline advances every clock (no enable). clr (= txn_clr) clears every valid, priority over capture.
// Tag bundle per stage: {valid, sample_q[6:0], first, last}.
[blk_pre]
// stage 0, registered
x_in = {{2{in_i[15]}}, in_i, 6'd0};   y_in = {{2{in_q[15]}}, in_q, 6'd0};      // signed24 F21
z_in = {in_phase, 8'd0};                                                       // signed24, 1 turn = 2^24
pos  = $signed(z_in) >  $signed(24'sd4194304);                                 // z > 2^22
neg  = $signed(z_in) < -$signed(24'sd4194304);                                 // z < -2^22
x0_d = (pos | neg) ? -x_in : x_in;   y0_d = (pos | neg) ? -y_in : y_in;
z0_d = pos ? z_in - 24'd8388608 : neg ? z_in + 24'd8388608 : z_in;            // +-2^23, result in [-2^22, 2^22]
x0_q <= x0_d; y0_q <= y0_d; z0_q <= z0_d; tag0_q <= {in_sample_q, in_first, in_last};
v0_q <= clr ? 1'b0 : in_valid @(rst=1'b0);
[mem_atan]
// constant ROM ATAN24[j] = RNE(atan(2^-j) / (2*pi) * 2^24), source 07 section 7
atan(j) = {24'd2097152, 24'd1238021, 24'd654136, 24'd332050, 24'd166669, 24'd83416, 24'd41718, 24'd20860,
           24'd10430, 24'd5215, 24'd2608, 24'd1304, 24'd652, 24'd326, 24'd163, 24'd81}[j];
[blk_iter]
// generate j = 0..15: stage j+1 registers from stage j (old x, y, z)
dir  = ~z_j_q[23];                                                              // z >= 0
xs   = x_j_q >>> j;  ys = y_j_q >>> j;                                          // arithmetic shift, no rounding
xn25 = dir ? sext25(x_j_q) - sext25(ys) : sext25(x_j_q) + sext25(ys);
yn25 = dir ? sext25(y_j_q) + sext25(xs) : sext25(y_j_q) - sext25(xs);
zn   = dir ? z_j_q - atan(j) : z_j_q + atan(j);                                 // signed24 wrap
of   = (xn25[24] != xn25[23]) | (yn25[24] != yn25[23]);                         // outside signed24
x_j1_q <= xn25[23:0]; y_j1_q <= yn25[23:0]; z_j1_q <= zn; tag_j1_q <= tag_j_q;
ovf_j1_q <= (j == 0) ? of : ovf_j_q | of;   v_j1_q <= clr ? 1'b0 : v_j_q @(rst=1'b0);
[blk_out]
// output stage from stage 16: RNE(x / 64), saturate to signed18 (only +131072 can exceed)
ax = |x16_q|;  vx = ax[23:6] + ((ax[5:0] > 6'd32) | ((ax[5:0] == 6'd32) & ax[6]));   // 19 bits, same for y
ox = x16_q[23] ? -vx : vx;  sat_x = ~x16_q[23] & (vx > 19'd131071);  out_i_d = sat_x ? 18'd131071 : ox[17:0];
out_i_q <= out_i_d; out_q_q <= out_q_d; out tags <= tag16_q;
out_valid_q <= clr ? 1'b0 : v16_q @(rst=1'b0);
ovf_err_q   <= clr ? 1'b0 : v16_q & (ovf16_q | sat_x | sat_y) @(rst=1'b0);
out_valid = out_valid_q; out_i = out_i_q; out_q = out_q_q; out_sample_q/out_first/out_last = output tag registers; ovf_err = ovf_err_q;
[bus_otag]
{out_sample_q, out_first, out_last} = out_tag_q;
